export type ParsedSubmitReviewInstruction<
  TProgram extends string = typeof TESSERA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    order: TAccountMetas[1];
    review: TAccountMetas[2];
    /** other party to this order before any score moves. */
    subject: TAccountMetas[3];
    subjectAgent: TAccountMetas[4];
    reviewerAgent: TAccountMetas[5];
    pair: TAccountMetas[6];
    reviewer: TAccountMetas[7];
    payer: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: SubmitReviewInstructionData;
};

export function parseSubmitReviewInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSubmitReviewInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      order: getNextAccount(),
      review: getNextAccount(),
      subject: getNextAccount(),
      subjectAgent: getNextAccount(),
      reviewerAgent: getNextAccount(),
      pair: getNextAccount(),
      reviewer: getNextAccount(),
      payer: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSubmitReviewInstructionDataDecoder().decode(instruction.data),
  };
}
